diff --git a/src/knownhost.c b/src/knownhost.c
index 2bd41de..8fbc9af 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -122,6 +122,7 @@ static struct libssh2_knownhost *knownhost_to_external(struct known_host *node)
 }

 #define KNOWNHOST_MAX_LEN  (1024 * 1024)
+#define KNOWNHOST_NAME_MAX 255

 static int knownhost_add(LIBSSH2_KNOWNHOSTS *hosts,
                          const char *host, const char *salt,
@@ -323,6 +324,14 @@ int libssh2_knownhost_add(LIBSSH2_KNOWNHOSTS *hosts,
                           const char *key, size_t keylen,
                           int typemask, struct libssh2_knownhost **store)
 {
+    /* plain names are matched through a fixed-size buffer, keep them
+       within the per-pattern limit the file reader applies */
+    if(hosts && host && (typemask & LIBSSH2_KNOWNHOST_TYPE_MASK) ==
+       LIBSSH2_KNOWNHOST_TYPE_PLAIN &&
+       strlen(host) > KNOWNHOST_NAME_MAX)
+        return ssh2_err(hosts->session, LIBSSH2_ERROR_OUT_OF_BOUNDARY,
+                        "Hostname too long");
+
     return knownhost_add(hosts, host, salt, NULL, 0, key, keylen, NULL,
                          0, typemask, store);
 }
@@ -355,6 +364,14 @@ int libssh2_knownhost_addc(LIBSSH2_KNOWNHOSTS *hosts,
                            const char *comment, size_t commentlen,
                            int typemask, struct libssh2_knownhost **store)
 {
+    /* plain names are matched through a fixed-size buffer, keep them
+       within the per-pattern limit the file reader applies */
+    if(hosts && host && (typemask & LIBSSH2_KNOWNHOST_TYPE_MASK) ==
+       LIBSSH2_KNOWNHOST_TYPE_PLAIN &&
+       strlen(host) > KNOWNHOST_NAME_MAX)
+        return ssh2_err(hosts->session, LIBSSH2_ERROR_OUT_OF_BOUNDARY,
+                        "Hostname too long");
+
     return knownhost_add(hosts, host, salt, NULL, 0, key, keylen,
                          comment, commentlen, typemask, store);
 }
@@ -386,14 +403,13 @@ static int knownhost_hex_value(char c)
     return -1;
 }

-static int knownhost_parse_ipv4(const char *src, const char *end,
-                                unsigned char result[4])
+static int knownhost_parse_ipv4(const char *src, unsigned char result[4])
 {
     unsigned int value = 0;
     size_t digits = 0;
     size_t count = 0;

-    while(src < end) {
+    while(*src) {
         if(*src >= '0' && *src <= '9') {
             if(digits == 3 || (digits && !value))
                 return 0;
@@ -419,17 +435,16 @@ static int knownhost_parse_ipv4(const char *src, const char *end,
     return 1;
 }

-static int knownhost_parse_ipv6(const char *src, size_t len,
-                                unsigned char result[16])
+static int knownhost_parse_ipv6(const char *src, unsigned char result[16])
 {
     unsigned short words[8];
     const char *p = src;
-    const char *end = src + len;
+    const char *end = src + strlen(src);
     size_t count = 0;
     int compressed = -1;
     size_t i;

-    if(!len)
+    if(p == end)
         return 0;

     memset(words, 0, sizeof(words));
@@ -458,7 +473,7 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         if(p < end && *p == '.') {
             unsigned char ipv4[4];

-            if(count > 6 || !knownhost_parse_ipv4(part, end, ipv4))
+            if(count > 6 || !knownhost_parse_ipv4(part, ipv4))
                 return 0;

             words[count++] =
@@ -554,6 +569,12 @@ static int knownhost_plain_match(const char *host, const char *known)
     size_t known_len;
     unsigned char host_binary[16];
     unsigned char known_binary[16];
+    /* Scratch buffers to null-terminate the address spans for the
+       parsers. The checked host comes from the API and can have any
+       length, while stored plain patterns are capped at
+       KNOWNHOST_NAME_MAX bytes. */
+    char host_addr[46];  /* longest IPv6 literal text form */
+    char known_addr[KNOWNHOST_NAME_MAX + 1];

     if(!strcmp(host, known))
         return 1;
@@ -567,8 +588,17 @@ static int knownhost_plain_match(const char *host, const char *known)
        strcmp(host_suffix, known_suffix))
         return 0;

-    if(!knownhost_parse_ipv6(host_address, host_len, host_binary) ||
-       !knownhost_parse_ipv6(known_address, known_len, known_binary))
+    if(host_len >= sizeof(host_addr))
+        /* the checked host cannot be an IPv6 literal */
+        return 0;
+
+    memcpy(host_addr, host_address, host_len);
+    host_addr[host_len] = '\0';
+    memcpy(known_addr, known_address, known_len);
+    known_addr[known_len] = '\0';
+
+    if(!knownhost_parse_ipv6(host_addr, host_binary) ||
+       !knownhost_parse_ipv6(known_addr, known_binary))
         return 0;

     return !memcmp(host_binary, known_binary, sizeof(host_binary));

diff --git a/src/knownhost.c b/src/knownhost.c
index ad8a6d8..f7b63c1 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -895,14 +895,13 @@ static int knownhost_line_legacy(LIBSSH2_KNOWNHOSTS *hosts,
            name to the collection */
         if(name == host || *(name - 1) == ',') {

-            char hostbuf[256];
+            /* patterns are not length-limited, allocate the buffer to
+               fit */
+            char *hostbuf = SSH2_ALLOC(hosts->session, namelen + 1);

-            /* make sure we do not overflow the buffer */
-            if(namelen >= sizeof(hostbuf) - 1)
-                return ssh2_err(hosts->session,
-                                LIBSSH2_ERROR_METHOD_NOT_SUPPORTED,
-                                "Failed to parse known_hosts line "
-                                "(unexpected length)");
+            if(!hostbuf)
+                return ssh2_err(hosts->session, LIBSSH2_ERROR_ALLOC,
+                                "Unable to allocate memory for hostname");

             /* copy hostname to the temp buffer and null-terminate */
             memcpy(hostbuf, name, namelen);
@@ -914,6 +913,7 @@ static int knownhost_line_legacy(LIBSSH2_KNOWNHOSTS *hosts,
                                comment, commentlen,
                                key_type | LIBSSH2_KNOWNHOST_TYPE_PLAIN |
                                LIBSSH2_KNOWNHOST_KEYENC_BASE64, NULL);
+            SSH2_FREE(hosts->session, hostbuf);
             if(rc)
                 return rc;
